import { pascal, camel } from "./compiler.mjs";
export const csIdentifier = (value) => "@" + value;
export const banner =
  "// Generated by pnpm generate:sdk. Do not edit directly.\n";
export const xml = (value = "") =>
  value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;");
export function text(value = "") {
  return value
    .replace(
      /\]\((#[^)]*|\/[^)]*)\)/g,
      (_, url) =>
        `](${url.startsWith("#") ? "https://docs.facturapi.io/api/" : "https://docs.facturapi.io"}${url})`,
    )
    .replaceAll("*/", "* /");
}
export function doc(value, indent = "") {
  return `${indent}/// <summary>\n${text(value)
    .split("\n")
    .map((line) => `${indent}/// ${xml(line)}`)
    .join("\n")}\n${indent}/// </summary>\n`;
}
export function fieldType(field, optional = true) {
  const type =
    field.kind === "model" || field.kind === "parameter"
      ? field.ref
      : field.kind === "array"
        ? `List<${fieldType(field.item, false)}>`
        : field.kind === "pagination"
          ? `SearchResult<${fieldType(field.item, false)}>`
          : field.kind === "map"
            ? `Dictionary<string, ${fieldType(field.item, false)}>`
            : field.kind === "union"
              ? `OneOf<${[...new Set(field.variants.map((variant) => fieldType(variant, false).replace(/\?$/, "")))].join(", ")}>`
              : field.kind === "inputDate"
                ? "OneOf<string, DateTime, DateTimeOffset>"
                : {
                    string: "string",
                    date: "DateTime",
                    boolean: "bool",
                    integer: "int",
                    number: "decimal",
                    binary: "Stream",
                    any: "object",
                    null: "object",
                    never: "object",
                    void: "void",
                  }[field.kind];
  if (type === "void") return type;
  return field.kind === "any" ||
    field.kind === "null" ||
    field.nullable ||
    (optional && !field.required)
    ? type + "?"
    : type;
}
export function description(field) {
  return [
    field.description || field.name,
    field.values &&
      `Valores: ${field.values.map((value) => JSON.stringify(value)).join(", ")}.`,
    field.required ? "Requerido." : "Opcional.",
    field.nullable && "Admite null.",
  ]
    .filter(Boolean)
    .join("\n");
}
export function renderModels(contract) {
  const outputs = new Map();
  for (const model of contract.models) {
    const parent = contract.models.find(
      (candidate) => candidate.name === model.parent,
    );
    let content =
      banner +
      "#nullable enable\nusing System;\nusing System.IO;\nusing System.Collections.Generic;\nusing Newtonsoft.Json;\nusing Newtonsoft.Json.Linq;\n\nnamespace Facturapi\n{\n";
    const discriminated = Object.entries(model.variantMappings || {}).flatMap(
      ([key, cases]) => {
        return model.properties
          .filter((field) => field.kind === "union")
          .flatMap((field) => {
            const variants = new Set(
              field.variants.map((variant) =>
                fieldType(variant, false).replace(/\?$/, ""),
              ),
            );
            const values = Object.entries(cases).filter(
              ([, fields]) => fields[field.name],
            );
            const targets = new Set(
              values.map(([, fields]) =>
                fieldType(fields[field.name], false).replace(/\?$/, ""),
              ),
            );
            return values.length > 1 &&
              targets.size === variants.size &&
              [...targets].every((type) => variants.has(type))
              ? [{ key, field, values }]
              : [];
          });
      },
    );
    content +=
      doc(model.generic ? "Resultados paginados." : model.description, "    ") +
      (discriminated.length
        ? `    [JsonConverter(typeof(${model.name}JsonConverter))]\n`
        : "") +
      `    public class ${model.name}${model.generic ? "<T>" : ""}${model.parent ? " : " + model.parent : model.input ? " : Dictionary<string, object?>" : ""}\n    {\n`;
    const fixed = model.input
      ? model.properties.filter(
          (field) =>
            ["type", "status"].includes(field.name) &&
            field.values?.length === 1 &&
            !field.nullable,
        )
      : [];
    const required = model.input
      ? model.properties.filter(
          (field) => field.required && !fixed.includes(field),
        )
      : [];
    if (required.length || fixed.length) {
      content += doc(`Crea ${model.name}.`, "        ");
      for (const field of required)
        content += `        /// <param name="${camel(field.name)}">${xml(text(description(field))).replaceAll("\n", " ")}</param>\n`;
      content += `        public ${model.name}(${required.map((field) => `${fieldType(field)} ${csIdentifier(camel(field.name))}`).join(", ")})${
        parent
          ? " : base(" +
            parent.properties
              .filter(
                (field) =>
                  field.required &&
                  !(
                    ["type", "status"].includes(field.name) &&
                    field.values?.length === 1 &&
                    !field.nullable
                  ),
              )
              .map((field) => {
                const own = model.properties.find(
                  (candidate) => candidate.name === field.name,
                );
                return fixed.includes(own)
                  ? JSON.stringify(own.values[0])
                  : csIdentifier(camel(field.name));
              })
              .join(", ") +
            ")"
          : ""
      }\n        {\n${required
        .map(
          (field) =>
            `            this[${JSON.stringify(field.name)}] = ${csIdentifier(camel(field.name))}${["union", "inputDate"].includes(field.kind) ? (fieldType(field).endsWith("?") ? "?.Value" : ".Value") : ""};`,
        )
        .concat(
          fixed.map(
            (field) =>
              `            this[${JSON.stringify(field.name)}] = ${JSON.stringify(field.values[0])};`,
          ),
        )
        .join("\n")}\n        }\n\n`;
    }
    for (const field of model.properties) {
      const type =
        model.name === "TaxInfoValidation" && field.name === "errors"
          ? "TaxInfoError[]"
          : fieldType(field);
      content += doc(description(field), "        ");
      if (model.input) {
        const modifier =
          [
            "Keys",
            "Values",
            "Count",
            "Comparer",
            "Item",
            "Add",
            "Remove",
            "Clear",
            "ContainsKey",
            "ContainsValue",
            "TryGetValue",
            "GetEnumerator",
            "CopyTo",
            "Equals",
            "GetHashCode",
            "GetType",
            "ToString",
          ].includes(pascal(field.name)) ||
          parent?.properties.some((property) => property.name === field.name)
            ? "new "
            : "";
        const isUnion = ["union", "inputDate"].includes(field.kind);
        const getter =
          isUnion && type.endsWith("?")
            ? `TryGetValue(${JSON.stringify(field.name)}, out var value) && value != null ? ${type.slice(0, -1)}.FromValue(value) : default(${type})`
            : `TryGetValue(${JSON.stringify(field.name)}, out var value) ? ${isUnion ? type + ".FromValue(value)" : "(" + type + ")value!"} : default!`;

        content += `        [JsonIgnore]\n        public ${modifier}${type} ${pascal(field.name)}\n        {\n            get => ${getter};\n            set => this[${JSON.stringify(field.name)}] = ${isUnion ? "value" + (type.endsWith("?") ? "?.Value" : ".Value") : "value"};\n        }\n\n`;
      } else
        content += `        [JsonProperty(${JSON.stringify(field.name)})]\n        public ${type} ${pascal(field.name)} { get; set; } = default!;\n\n`;
    }
    if (!model.input && model.additional)
      content +=
        doc("Propiedades adicionales del objeto JSON.", "        ") +
        "        [JsonExtensionData]\n        public IDictionary<string, JToken>? AdditionalProperties { get; set; }\n";
    content += "    }\n}\n";
    if (discriminated.length) {
      let converter =
        banner +
        "#nullable enable\nusing System;\nusing Newtonsoft.Json;\nusing Newtonsoft.Json.Linq;\nnamespace Facturapi\n{\n" +
        `    internal sealed class ${model.name}JsonConverter : JsonConverter\n    {\n        public override bool CanWrite => false;\n        public override bool CanConvert(Type type) => type == typeof(${model.name});\n        public override void WriteJson(JsonWriter writer, object? value, JsonSerializer serializer) => throw new NotSupportedException();\n        public override object? ReadJson(JsonReader reader, Type objectType, object? existingValue, JsonSerializer serializer)\n        {\n            if (reader.TokenType == JsonToken.Null) return null;\n            var data = JObject.Load(reader);\n            var result = new ${model.name}();\n`;
      for (const { field } of discriminated)
        converter += `            var ${csIdentifier(camel(field.name))} = data[${JSON.stringify(field.name)}];\n            data.Remove(${JSON.stringify(field.name)});\n`;
      converter +=
        "            using (var content = data.CreateReader()) serializer.Populate(content, result);\n";
      for (const { key, field, values } of discriminated) {
        converter += `            if (${csIdentifier(camel(field.name))} != null && ${csIdentifier(camel(field.name))}.Type != JTokenType.Null)\n            {\n                switch ((string?)data[${JSON.stringify(key)}])\n                {\n`;
        for (const [value, fields] of values)
          converter += `                    case ${JSON.stringify(value)}: result.${pascal(field.name)} = ${csIdentifier(camel(field.name))}.ToObject<${fieldType(fields[field.name], false).replace(/\?$/, "")}>(serializer)!; break;\n`;
        converter +=
          '                    default: throw new JsonSerializationException("Unknown discriminator value for a documented response alternative.");\n                }\n            }\n';
      }
      converter += "            return result;\n        }\n    }\n}\n";
      outputs.set(`Models/${model.name}.JsonConverter.cs`, converter);
    }
    outputs.set(
      `Models/${model.input ? "Inputs/" : ""}${model.name}.cs`,
      content,
    );
  }
  // Typed alternatives serialize as their value, without a JSON envelope.
  const arities = new Set([2]);
  for (const model of contract.models)
    for (const field of model.properties)
      for (const match of fieldType(field).matchAll(/OneOf</g)) {
        // Compute nested arities from the rendered type's balanced generic brackets.
        const value = fieldType(field).slice(match.index + 6);
        let depth = 0,
          arity = 1;
        for (const char of value) {
          if (char === "<") depth++;
          else if (char === ">" && depth-- === 0) break;
          else if (char === "," && depth === 0) arity++;
        }
        arities.add(arity);
      }
  for (const method of contract.methods.filter((method) => method.response)) {
    if (method.response.kind === "union")
      arities.add(
        new Set(
          method.response.variants.map((variant) => fieldType(variant, false)),
        ).size,
      );
  }
  for (const count of arities) {
    if (count < 2) continue;
    const types = Array.from(
      { length: count },
      (_, index) => `T${index + 1}`,
    ).join(", ");
    outputs.set(
      `Models/OneOf${count}.cs`,
      banner +
        `#nullable enable\nusing System;\nusing Newtonsoft.Json;\n\nnamespace Facturapi\n{\n` +
        doc(
          "Una de las alternativas del contrato. Se serializa sin envoltura JSON.",
          "    ",
        ) +
        `    [JsonConverter(typeof(OneOfConverter))]\n    public readonly struct OneOf<${types}> : IOneOfValue\n    {\n` +
        doc("Valor de la alternativa seleccionada.", "        ") +
        `        public object? Value { get; }\n        private OneOf(object? value) { Value = value; }\n        internal static OneOf<${types}> FromValue(object? value) => new OneOf<${types}>(value);\n` +
        Array.from(
          { length: count },
          (_, index) =>
            doc(`Selecciona la alternativa ${index + 1}.`, "        ") +
            `        public static implicit operator OneOf<${types}>(T${index + 1} value) => new OneOf<${types}>(value);\n`,
        ).join("") +
        doc(
          "Obtiene el valor cuando coincide con el tipo solicitado.",
          "        ",
        ) +
        `        public bool TryGet<T>(out T value)\n        {\n            if (Value is T match) { value = match; return true; }\n            value = default!;\n            return false;\n        }\n` +
        doc("Representación del valor seleccionado.", "        ") +
        `        public override string ToString() => Value?.ToString() ?? string.Empty;\n    }\n}\n`,
    );
  }
  return outputs;
}
